def is_subset_sum(arr, target, n): 
    dp = [[False for _ in range(target+1)] for _ in range(n+1)]
    for i in range(n+1):
        for j in range(target+1):
            if i==0:
                dp[i][j]=False
            elif j==0:
                dp[i][j]=True
            elif arr[i-1]<=j:
                dp[i][j]=dp[i-1][j-arr[i-1]] or dp[i-1][j]
            else:
                dp[i][j]=dp[i-1][j]
    return dp[n][target]

