def binary_search(arr, x): 
  low = 0
  high = len(arr)-1
  while low <= high: 
    mid = (high+low)//2
    if arr[mid] == x: 
      return True
    elif arr[mid] < x: 
      low = mid+1
    else: 
      high = mid-1
  return False

import math
def calculate_polygons(x,y,z,w,v):
  polygons = []
  for i in range(x):
    polygon = []
    for j in range(y):
      for k in range(z):
        for l in range(w):
          for m in range(v):
            polygon.append(((i * 2 + j) * 2 + k) * 2 + l) * 2 + m)
    polygons.append(polygon)
  return polygons

