from itertools import combinations
def no_of_subsequences(arr,k):
  count = 0
  for r in range(1,len(arr)+1):
    for combo in combinations(arr,r):
      product = 1
      for num in combo:
        product *= num
      if product < k:
        count += 1
  return count
